{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Inogatran, a close peptidic analogue bearing a basic guanidine and a free carboxylate, had oral bioavailability <5% in healthy volunteers, directly supporting a low-F prediction for the query's ionizable amidine/acid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "DX-9065a, a clinical compound with strong basic amidino groups and a carboxylate, had human oral bioavailability of only 2–3%, attributed to the amidine moieties; the query contains the same permeability-limiting benzamidine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Melagatran, an amidine/carboxylate thrombin inhibitor, had oral bioavailability lowered to 0.9% after food intake, indicating that the fed state further impairs absorption of this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A benzamidine-containing carboxylate analogue had absolute bioavailability too low for oral use in humans, reinforcing the low-F pattern for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "AZD0837, a methoxyamidine prodrug lacking the free carboxylic acid, showed F of 22–55% in humans; this high value reflects prodrug masking of ionizable groups and does not transfer to the query's free amidine/acid form.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a free amidine/free carboxylate peptidomimetic. Close active analogues (inogatran, melagatran, DX-9065a) all show oral bioavailability below 10%, and fed conditions further lower melagatran to <1%. The only high-F analogue is a prodrug with masked ionizable groups, so it does not apply. Therefore the query is predicted to have F <20%.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule.",
    "Fed-state data for the exact query are unavailable; extrapolated from melagatran.",
    "The azetidine ring may alter permeability relative to proline analogues, but not enough to overcome the amidine/acid liabilities."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

